// ZoomInfo counterpart to wf25's "Parse request" -- same {propId, address}
// input contract so the app's Discover button can point at either source
// with the same body shape. Derives a 5-digit zip from the tail of the
// address (same regex idea as wf25's base_location extraction) since
// ZoomInfo's Search Companies filters on zipCode + zipCodeRadiusMiles, not
// a free-text location string.
//
// CATEGORY PARITY WITH CoreClaw (deliberate, per testing_plan.md Phase 4):
// search_category values written to Firestore MUST stay one of the same 9
// known strings wf25 already uses, because wf26 (Nearby Prospect Research
// & Draft) keys its fit-tier GROUPS map off exact matches on those 9
// strings. CATEGORY_KEYWORDS below translates each of those 9 category
// labels into a real ZoomInfo industryKeywords query under the hood --
// the label written to Firestore and the search term actually sent to
// ZoomInfo are deliberately different things.
const b = $json.body || {};
const propId = b.propId || '';
const address = b.address || '';
if (!propId) throw new Error('Missing body.propId');
if (!address) throw new Error('Missing body.address');

const zipMatch = address.match(/(\d{5})(?:-\d{4})?\s*$/);
const zipCode = zipMatch ? zipMatch[1] : (b.zip_code || '');
if (!zipCode) throw new Error('Could not derive a 5-digit zip from address, and no body.zip_code override was given.');

const radiusMiles = [10, 25, 50, 100, 250].includes(parseInt(b.zip_code_radius_miles, 10))
  ? parseInt(b.zip_code_radius_miles, 10) : 25;
const employeeRangeMax = b.employee_range_max ? String(b.employee_range_max) : '50';
const zoominfoContactsMax = b.zoominfo_contacts_max ? String(b.zoominfo_contacts_max) : '8';

const CATEGORY_KEYWORDS = {
  'import export company': 'import OR export OR importer OR exporter',
  'distribution company': 'distribution OR distributor',
  'wholesale distributor': 'wholesale',
  '3PL logistics company': '3PL OR logistics OR third party logistics',
  'freight forwarder': 'freight forwarding OR freight forwarder',
  'ecommerce fulfillment center': 'ecommerce fulfillment OR fulfillment center OR order fulfillment',
  'trucking company': 'trucking OR trucking company',
  'manufacturer': 'manufacturer OR manufacturing',
  'moving and storage company': 'moving OR storage OR self storage OR moving company'
};
const categories = (Array.isArray(b.categories) && b.categories.length) ? b.categories : Object.keys(CATEGORY_KEYWORDS);
const unknown = categories.filter(c => !CATEGORY_KEYWORDS[c]);
if (unknown.length) throw new Error(`Unknown category label(s): ${unknown.join(', ')}. Must be one of: ${Object.keys(CATEGORY_KEYWORDS).join(', ')}`);

return [{ json: { propId, address, zipCode, radiusMiles, employeeRangeMax, zoominfoContactsMax, categories, CATEGORY_KEYWORDS } }];

// Same static-data accumulator pattern as wf25's "Reset accumulator + fan
// out categories" -- one item per category, fed into the batch loop, reset
// on every fresh webhook call so an errored prior run never leaks in.
const ws = $getWorkflowStaticData('global');
ws.rows = [];
const ctx = $json;
return (ctx.categories || []).map(cat => ({ json: { ...ctx, category: cat, industryKeywords: ctx.CATEGORY_KEYWORDS[cat] } }));

// Real request shape confirmed live 2026-08-03 (workflow 29 test bench):
// {data:{type:"CompanySearch", attributes:{...filters}}}. page[number]/
// page[size] are URL query params, not body fields. Free endpoint --
// no credit cost. v1 takes only the first page (page[size]=100) per
// category; totalResults is still surfaced in the response for visibility
// if a category has more matches than that -- multi-page looping can be
// added later if a single Discover run needs the full set.
const ctx = $json;
const attrs = {
  zipCode: ctx.zipCode,
  zipCodeRadiusMiles: ctx.radiusMiles,
  employeeRangeMax: ctx.employeeRangeMax,
  zoominfoContactsMax: ctx.zoominfoContactsMax,
  industryKeywords: ctx.industryKeywords,
  excludeDefunctCompanies: true
};
return [{ json: {
  ...ctx,
  requestBody: { data: { type: 'CompanySearch', attributes: attrs } }
} }];

// Tags each result row with the search_category (one of the 9 known
// CoreClaw-parity strings, NOT the ZoomInfo industryKeywords string used
// to find it) and appends to the shared static-data accumulator, same
// convention as wf25's "Tag + accumulate results". No contact fields are
// populated here -- Discover only ever writes name/website/category, per
// the two-stage Discover(free)/Enrich(paid) split in testing_plan.md Phase
// 4. This keeps a single accidental click from spending credits.
//
// PARSING QUIRK (found 2026-08-03 live in n8n, wf29): ZoomInfo's
// application/vnd.api+json Content-Type isn't autodetected as JSON by
// n8n's HTTP Request node, so the real response can arrive as
// {data: "<json string>"} instead of a parsed object. Unwrap that here.
function parseResp(raw) {
  if (raw && typeof raw.data === 'string') {
    try { return JSON.parse(raw.data); } catch (e) { return raw; }
  }
  return raw;
}
const prev = $('Build Search Companies body').first().json;
const resp = parseResp($json || {});
const rows = Array.isArray(resp.data) ? resp.data : [];
const totalResults = resp.meta && typeof resp.meta.totalResults === 'number' ? resp.meta.totalResults : rows.length;
const ws = $getWorkflowStaticData('global');
ws.rows = ws.rows || [];
for (const r of rows) {
  const a = r.attributes || {};
  if (!r.id) continue; // no stable id to dedupe/write on -- skip
  ws.rows.push({
    place_cid: String(r.id),
    name: a.name || '',
    website: a.website || '',
    city: a.city || '',
    state: a.state || '',
    search_category: prev.category
  });
}
return [{ json: { ...prev, resultCount: rows.length, totalResults } }];

// Dedupe the FULL cross-category accumulator by place_cid -- first
// occurrence wins for search_category, same rule as wf25. Runs once, after
// the category loop's "done" output fires.
const ws = $getWorkflowStaticData('global');
const rows = ws.rows || [];
const byId = new Map();
for (const r of rows) {
  if (!byId.has(r.place_cid)) byId.set(r.place_cid, r);
}
const deduped = [...byId.values()];
ws.rows = []; // clear for the next run
const req = $('Parse request').first().json;
return [{ json: { propId: req.propId, categoriesRun: (req.categories || []).length, rows: deduped } }];

// Build the workflow-20 (generic Firestore writer) bulk_update payload --
// SAME endpoint and SAME action wf25 already uses, so masked-write safety
// (never bulk_create, only touches the fields listed here, never touches
// status/notes/attempts/archived/cold_draft on an existing doc) carries
// over unchanged. source:'zoominfo' distinguishes these rows from the 319
// legacy CoreClaw rows without needing to touch them at all.
const j = $json;
const nowIso = new Date().toISOString();
const items = (j.rows || []).map(r => ({
  id: r.place_cid,
  fields: {
    location: j.propId,
    place_cid: r.place_cid,
    name: r.name,
    website: r.website,
    city: r.city,
    state: r.state,
    search_category: r.search_category,
    source: 'zoominfo',
    last_seen_at: nowIso
  }
}));
return [{ json: { propId: j.propId, categoriesRun: j.categoriesRun, discovered: items.length, writerBody: { collection: 'site_outreach', action: 'bulk_update', items } } }];

const build = $('Build write payload').first().json;
const wrote = $json;
return [{ json: { ok: true, propId: build.propId, categoriesRun: build.categoriesRun, discovered: build.discovered, source: 'zoominfo', writerResponse: wrote } }];
